from pathlib import Path
import os,re
R=Path('Code2');C=R/'Code2.cpp';P=R/'PROGRESS.md';A=R/'CODE2_CONTINUITY_ADDENDUM.md';K=R/'RESUME_CHECKPOINT.md';F=R/'.batch95.fragment.cpp'
def norm(s):return s.rstrip()+"\n"
def integrate():
 c=C.read_text();f=F.read_text().rstrip()+"\n";assert 'constexpr u32 kVerifiedTranslatedBytes = 213958u;' in c and '// Batch 95:' not in c
 c=c.replace('constexpr u32 kVerifiedTranslatedBytes = 213958u;','constexpr u32 kVerifiedTranslatedBytes = 214028u;',1)
 m=re.search(r'(static_assert\(kVerifiedTranslatedBytes ==[\s\S]*?)(\);)',c);assert m;c=c[:m.start()]+m.group(1).rstrip()+' + 70u'+m.group(2)+c[m.end():]
 mark='\n} // namespace code2\n';assert c.endswith(mark);C.write_text(norm(c[:-len(mark)]+'\n\n'+f+mark))
 p=P.read_text();p=re.sub(r'object%20accounting-[0-9.]+%25','object%20accounting-91.07%25',p,count=1);p=re.sub(r'\*\*Verified translated instruction bytes:\*\* \*\*[0-9,]+\*\*','**Verified translated instruction bytes:** **214,028**',p,count=1);p=re.sub(r'\*\*Reconciled object bytes:\*\* \*\*[0-9,]+ / 239,698 = [0-9.]+% \([0-9.]+%\)\*\*','**Reconciled object bytes:** **218,302 / 239,698 = 91.0738% (91.07%)**',p,count=1);p=re.sub(r'\*\*Unresolved object bytes:\*\* \*\*[0-9,]+\*\*','**Unresolved object bytes:** **21,396**',p,count=1);P.write_text(norm(p.rstrip()+'''\n## Batch 95 — VGA map-mask and bounded string copy\n\nAdded **70 translated instruction bytes**, bringing accounting to **214,028 translated + 4,274 non-code = 218,302 / 239,698 = 91.0738% (91.07%)**. `3395C` emits the exact 16-bit VGA sequencer write `(mask.low8 << 8) | 02h` to port `03C4h` through an explicit hardware boundary. `33971` preserves the encoded bounded string-copy behavior: copy nonzero source bytes while count remains, then zero-fill every remaining destination byte and return the original destination. Next frontier: **`339A2`**.\n'''))
 a=A.read_text();A.write_text(norm(a.rstrip()+'''\n## CODE.2 Batch 95 checkpoint\n\nBatch 95 reconciles `3395C..339A1`: **70 translated bytes** and no separator bytes. Coverage is **218,302 / 239,698 = 91.0738% (91.07%)**, with **21,396 unresolved bytes**. Preserve the single 16-bit `OUT DX,AX` value/port at `3395C`, and for `33971` preserve the no-source-advance/no-count-decrement behavior when the NUL terminator is first observed before the zero-fill loop. Next frontier is `339A2`.\n'''))
def verify():
 c=C.read_text();p=P.read_text();assert 'constexpr u32 kVerifiedTranslatedBytes = 214028u;' in c and 'constexpr u32 kVerifiedNonCodeBytes = 4274u;' in c;assert 'function_3395c' in c and 'Runtime95Boundary' in c and '0x03C4u' in c and 'function_33971' in c and '218,302 / 239,698 = 91.0738% (91.07%)' in p
def checkpoint():
 sha=os.environ['BATCH_SHA'];K.write_text(norm(f'''# CODE.2 resume checkpoint\n\nDurable handoff anchor; live repository/binary evidence wins.\n\n## Last committed substantive decompilation state\n- Last substantive batch commit: `{sha}` — `Integrate CODE.2 decompilation batch 95`.\n- Verified translated instruction bytes: **214,028**.\n- Proven non-code/data bytes: **4,274**.\n- Reconciled object bytes: **218,302 / 239,698 = 91.0738% (91.07%)**.\n- Unresolved object bytes: **21,396**.\n- Last integrated ownership fold: `3395C..339A1`.\n- Next independently decoded instruction boundary: **`339A2`**.\n\n## Immutable identity\n- `CODE.2` SHA-256: `853e0a4dfcabebcfeecb975cf2a92b92eb4d94806d835ad30a0bab3e265bd314`.\n- Object-1 SHA-256: `014952c4f003c548d928984825bab57dff54ce962dbfae21d7260f19fd3a62f3`.\n\n## Mandatory overlap anchor for next resume\n- Window `[0x33960,0x33A40)` — 224 bytes; SHA-256 `7f2e8b802fd8b354ee95c06de55156364eadf9e3ec41c3b79a76c26b042435db`.\n- Narrow `[0x339A0,0x33A00)` — 96 bytes; SHA-256 `82b52b929b46d678db6fc7bbb5823db5d8d1e4385c83fe991a3773052cf45dfe`.\n- Narrow bytes: `5bc353528b44240c8b5424108b5c241451505289dab41acd21595ab44ecd21e8c856000089dae827000000595a5bc38b4424045289c2b41acd21e836000000b44fcd21e8a4560000e8050000005ac331c0c3803d622601000975195053515657`.\n\nInterpretation: `33970` and `339A1` are independent RETs for the two Batch-95 helpers; there are no separator bytes; `339A2` begins the DOS DTA/find-first wrapper. No Batch 96 bytes are counted.\n'''))
